"use client";
import { useNotifications } from "./hooks/useNotifications";
import { useRef, useEffect, useState } from "react";
import { useSocketConnection } from "./hooks/useSocketConnection";
import { NotificationHeader } from "./Components/NotificationHeader";
import { NotificationCard } from "./Components/NotificationCard";
import { EmptyState } from "./Components/EmptyState";
import LoadingSpinner from "@/Components/LoadingSpinner";
import type { Contact } from "@/store/contactSlice";
import fetchServerPage from "./virtualization";

export default function NotificationsPage() {
  const { notifications, handleMarkAsRead } = useNotifications();
  const scrollRef = useRef<HTMLDivElement>(null);
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [offset, setOffset] = useState(0);
  const [loading, setLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [initialLoad, setInitialLoad] = useState(true);

  const { isConnected, showReconnectMessage, dismissReconnectMessage } =
    useSocketConnection();

  // Load initial contacts
  useEffect(() => {
    const loadInitial = async () => {
      setLoading(true);
      const result = await fetchServerPage(15, 0);
      setContacts(result.rows);
      setOffset(15);
      setHasMore(result.hasMore);
      setLoading(false);
      setInitialLoad(false);
    };
    loadInitial();
  }, []);

  // Handle scroll to bottom
  const handleScroll = async () => {
    if (!scrollRef.current || loading || !hasMore) return;

    const { scrollTop, scrollHeight, clientHeight } = scrollRef.current;
    if (scrollTop + clientHeight >= scrollHeight - 10) {
      setLoading(true);
      const result = await fetchServerPage(15, offset);
      
      if (result.rows.length > 0) {
        setContacts((prev) => {
          const newContacts = [...prev, ...result.rows];
          // Remove first 10 if we have more than 25 items
          if (newContacts.length > 25) {
            return newContacts.slice(10);
          }
          return newContacts;
        });
        setOffset((prev) => prev + 15);
        setHasMore(result.hasMore);
      } else {
        setHasMore(false);
      }
      setLoading(false);
    }
  };

  if (initialLoad) {
    return (
      <div className="flex justify-center items-center">
        <LoadingSpinner />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <NotificationHeader
        isConnected={isConnected}
        showReconnectMessage={showReconnectMessage}
        onDismissReconnect={dismissReconnectMessage}
      />

      {/* Contacts List */}
      <div
        ref={scrollRef}
        onScroll={handleScroll}
        className=" space-y-4"
      >
        {contacts.length === 0 ? (
          <EmptyState />
        ) : (
          contacts.map((notification, index) => (
            <NotificationCard
              key={notification.id || `notification-${index}`}
              notification={notification}
              onMarkAsRead={handleMarkAsRead}
            />
          ))
        )}
        
        {loading && (
          <div className="flex justify-center py-4">
            <LoadingSpinner />
          </div>
        )}
        
        {!hasMore && contacts.length > 0 && (
          <div className="text-center text-gray-500 py-4">
            No more contacts
          </div>
        )}
      </div>
    </div>
  );
}
